                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for k in range(abs(r2-r1) + 1):
                    r, c = r1+k*dr, c1+k*dc
                    if out[r][c] == bg:
                        out[r][c] = 1
                one_lines.add((slope, r1-c1 if slope == 1 else r1+c1))

    # A 6 extends on the perpendicular diagonal only if that diagonal
    # intersects one of the 1-lines at an integer grid position.
    for r0, c0 in sixes:
        for r in range(h):
            c = c0 + (r-r0)
            if not (0 <= c < w):
                continue
            intersects = False
            for slope, intercept in one_lines:
                if slope == -1:
                    # 1-line r+c=intercept; 6-line c-r=c0-r0
                    if (intercept + c0-r0) % 2 == 0:
                        intersects = True
                else:
                    # 1-line r-c=intercept; parallel to this 6-line, so skip
                    pass
            if intersects and out[r][c] == bg:
                out[r][c] = 6
    return out
